const CODE_EXT = new Set(["nim", "wit", "wat", "sol", "v", "sv"]);

svnIconAssets["expand-branches"] = ['<svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="m4.5 6 3.5-3.5L11.5 6m-7 4 3.5 3.5 3.5-3.5" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"/></svg>'];

const iconTemplates = new Map();
let iconInstance = 0;

function svnIcon(name) {
  const variants = svnIconAssets[name];
  let template = iconTemplates.get(name);
  if (!template) {
    template = document.createElement("template");
    template.innerHTML = variants.length === 1 ? variants[0] : variants
      .map((svg, index) => svg.replace("<svg", '<svg data-variant="' + (index ? "dark" : "light") + '"'))
      .join("");
    iconTemplates.set(name, template);
  }
  const icon = document.createElement("span");
  icon.className = "svg-icon";
  icon.setAttribute("aria-hidden", "true");
  icon.append(template.content.cloneNode(true));
  for (const svg of icon.children) {
    const ids = svg.querySelectorAll("[id]");
    if (!ids.length) continue;
    const prefix = "svn-icon-" + ++iconInstance + "-";
    for (const node of ids) node.id = prefix + node.id;
    for (const node of svg.querySelectorAll("*")) {
      for (const attr of node.attributes) {
        if (attr.localName === "href" && attr.value.startsWith("#")) {
          attr.value = "#" + prefix + attr.value.slice(1);
        } else if (attr.value.includes("url(#")) {
          attr.value = attr.value.replaceAll("url(#", "url(#" + prefix);
        }
      }
    }
  }
  return icon;
}

function fileIcon(path, directory = false) {
  if (directory) return svnIcon("folder");
  const name = path.replaceAll("\\", "/").split("/").at(-1).toLowerCase();
  const named = FILE_NAMES.get(name) ?? NAME_PATTERNS.find(([pattern]) => pattern.test(name))?.[1];
  if (named) return svnIcon(named);
  const dot = name.lastIndexOf(".");
  if (dot <= 0) return svnIcon("file-text");
  const extension = name.slice(dot + 1);
  const previous = name.lastIndexOf(".", dot - 1);
  const compound = previous > 0 ? EXT_ICONS.get(name.slice(previous + 1)) : undefined;
  return svnIcon(compound ?? EXT_ICONS.get(extension) ?? (CODE_EXT.has(extension) ? "file-code" : "file-unknown"));
}
